CREATE TABLE IF NOT EXISTS v10_task_links (company_id BIGINT UNSIGNED NOT NULL,task_id BIGINT UNSIGNED NOT NULL,entity_type VARCHAR(64) NOT NULL,entity_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(company_id,task_id,entity_type,entity_id),KEY ix_v10_task_links_entity(company_id,entity_type,entity_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
